-- =============================================================================
-- SUBSCRIPTIONS TABLE
-- =============================================================================
-- Stores webhook subscription configurations
CREATE TABLE {{obj "subscriptions"}} (
    -- Identity
    id VARCHAR(255) PRIMARY KEY,
    tenant_id VARCHAR(255) NOT NULL,

    -- Endpoint configuration
    url TEXT NOT NULL,
    secret VARCHAR(512) NOT NULL, -- HMAC secret for signing

    -- Event filtering
    event_types TEXT[] NOT NULL,

    -- Metadata filtering
    filters JSONB DEFAULT '{}'::jsonb,

    -- Subscription state
    status VARCHAR(50) NOT NULL DEFAULT 'active',

    -- Retry configuration (stored as JSONB for flexibility)
    retry_policy JSONB NOT NULL DEFAULT '{
        "max_attempts": 10,
        "initial_backoff": "1s",
        "max_backoff": "1h",
        "backoff_factor": 2.0
    }'::jsonb,

    -- Custom headers for delivery
    headers JSONB DEFAULT '{}'::jsonb,

    -- Additional metadata
    metadata JSONB DEFAULT '{}'::jsonb,

    -- Timestamps
    created_at TIMESTAMP WITH TIME ZONE NOT NULL DEFAULT NOW(),
    updated_at TIMESTAMP WITH TIME ZONE NOT NULL DEFAULT NOW(),

    -- Constraints
    CONSTRAINT {{ident "chk" "subscriptions_status"}} CHECK (status IN ('active', 'paused', 'disabled')),
    CONSTRAINT {{ident "chk" "subscriptions_url"}} CHECK (LENGTH(TRIM(url)) > 0),
    CONSTRAINT {{ident "chk" "subscriptions_secret"}} CHECK (LENGTH(TRIM(secret)) > 0),
    CONSTRAINT {{ident "chk" "subscriptions_events"}} CHECK (array_length(event_types, 1) > 0)
);

-- Indexes for subscriptions
CREATE INDEX {{ident "idx" "subscriptions_tenant_id"}} ON {{obj "subscriptions"}}(tenant_id);
CREATE INDEX {{ident "idx" "subscriptions_status"}} ON {{obj "subscriptions"}}(status);
CREATE INDEX {{ident "idx" "subscriptions_event_types"}} ON {{obj "subscriptions"}} USING GIN(event_types);
CREATE INDEX {{ident "idx" "subscriptions_created_at"}} ON {{obj "subscriptions"}}(created_at DESC);
CREATE UNIQUE INDEX {{ident "idx" "subscriptions_tenant_url"}} ON {{obj "subscriptions"}}(tenant_id, url);
CREATE INDEX {{ident "idx" "subscriptions_filters"}} ON {{obj "subscriptions"}} USING GIN(filters);

-- Comments (include schema version for version tracking)
COMMENT ON TABLE {{obj "subscriptions"}} IS 'go-hookd schema v0.6.0 - Webhook subscription configurations';
COMMENT ON COLUMN {{obj "subscriptions"}}.id IS 'Prefixed nanoID (sub_*)';
COMMENT ON COLUMN {{obj "subscriptions"}}.tenant_id IS 'Tenant identifier for multi-tenancy';
COMMENT ON COLUMN {{obj "subscriptions"}}.event_types IS 'Array of event types this subscription listens to';
COMMENT ON COLUMN {{obj "subscriptions"}}.filters IS 'JSONB filter conditions for metadata-based filtering';
COMMENT ON COLUMN {{obj "subscriptions"}}.retry_policy IS 'Retry configuration as JSONB';

-- =============================================================================
-- DELIVERIES TABLE
-- =============================================================================
-- Stores webhook delivery queue and state
-- Supports both subscription-based and inline (ad-hoc) deliveries
CREATE TABLE {{obj "deliveries"}} (
    -- Identity
    id VARCHAR(255) PRIMARY KEY,
    subscription_id VARCHAR(255), -- NULLABLE for inline deliveries
    tenant_id VARCHAR(255) NOT NULL,

    -- Event data
    event_type VARCHAR(255) NOT NULL,
    payload JSONB NOT NULL,

    -- Inline delivery fields (only used when subscription_id is NULL)
    url TEXT,                    -- Direct URL for inline deliveries
    secret VARCHAR(512),         -- HMAC secret for inline deliveries

    -- Delivery state
    status VARCHAR(50) NOT NULL DEFAULT 'pending',
    attempt_count INTEGER NOT NULL DEFAULT 0,
    max_attempts INTEGER NOT NULL,

    -- Retry scheduling
    next_retry_at TIMESTAMP WITH TIME ZONE,

    -- Completion tracking
    completed_at TIMESTAMP WITH TIME ZONE,

    -- Timestamps
    created_at TIMESTAMP WITH TIME ZONE NOT NULL DEFAULT NOW(),

    -- Caller-supplied idempotency key, sent as X-Webhook-Idempotency-Key
    -- (v0.11.0; added to existing schemas additively by EnsureSchema)
    idempotency_key VARCHAR(255),

    -- The retry budget the delivery was queued with; a dead-letter redrive
    -- renews exactly this much (v0.11.1; added in place by EnsureSchema)
    attempt_budget INTEGER,

    -- Constraints
    CONSTRAINT {{ident "chk" "deliveries_status"}} CHECK (status IN ('pending', 'success', 'failed', 'dead_letter')),
    CONSTRAINT {{ident "chk" "deliveries_attempts"}} CHECK (attempt_count >= 0),
    CONSTRAINT {{ident "chk" "deliveries_max_attempts"}} CHECK (max_attempts >= 0),
    CONSTRAINT {{ident "chk" "deliveries_target"}} CHECK (subscription_id IS NOT NULL OR url IS NOT NULL),

    -- Foreign keys (optional for inline deliveries)
    CONSTRAINT {{ident "fk" "deliveries_subscription"}}
        FOREIGN KEY (subscription_id)
        REFERENCES {{obj "subscriptions"}}(id)
        ON DELETE CASCADE
);

-- Indexes for deliveries (optimized for queue processing with SKIP LOCKED)
CREATE INDEX {{ident "idx" "deliveries_subscription_id"}} ON {{obj "deliveries"}}(subscription_id);
CREATE INDEX {{ident "idx" "deliveries_tenant_id"}} ON {{obj "deliveries"}}(tenant_id);
CREATE INDEX {{ident "idx" "deliveries_status"}} ON {{obj "deliveries"}}(status);
CREATE INDEX {{ident "idx" "deliveries_event_type"}} ON {{obj "deliveries"}}(event_type);
CREATE INDEX {{ident "idx" "deliveries_created_at"}} ON {{obj "deliveries"}}(created_at DESC);

-- Critical index for queue processing with SKIP LOCKED
CREATE INDEX {{ident "idx" "deliveries_pending_queue"}} ON {{obj "deliveries"}}(status, next_retry_at, created_at)
    WHERE status = 'pending';

-- Index for inline deliveries (deliveries without subscription)
CREATE INDEX {{ident "idx" "deliveries_inline"}} ON {{obj "deliveries"}}(tenant_id, event_type)
    WHERE subscription_id IS NULL;

-- Comments
COMMENT ON TABLE {{obj "deliveries"}} IS 'Webhook delivery queue and history';
COMMENT ON COLUMN {{obj "deliveries"}}.id IS 'Prefixed nanoID (dlv_*)';
COMMENT ON COLUMN {{obj "deliveries"}}.subscription_id IS 'NULL for inline deliveries';
COMMENT ON COLUMN {{obj "deliveries"}}.url IS 'Direct URL for inline deliveries (NULL for subscription-based)';
COMMENT ON COLUMN {{obj "deliveries"}}.secret IS 'HMAC secret for inline deliveries (NULL for subscription-based)';
COMMENT ON COLUMN {{obj "deliveries"}}.status IS 'Current delivery status';
COMMENT ON COLUMN {{obj "deliveries"}}.next_retry_at IS 'Scheduled time for next retry attempt';
COMMENT ON INDEX {{ident "idx" "deliveries_pending_queue"}} IS 'Optimized for SKIP LOCKED queue processing';
COMMENT ON CONSTRAINT {{ident "chk" "deliveries_target"}} ON {{obj "deliveries"}} IS 'Ensures delivery has either subscription_id OR url for inline delivery';

-- =============================================================================
-- DELIVERY_ATTEMPTS TABLE
-- =============================================================================
-- Stores history of all delivery attempts
CREATE TABLE {{obj "delivery_attempts"}} (
    -- Identity
    id VARCHAR(255) PRIMARY KEY,
    delivery_id VARCHAR(255) NOT NULL,

    -- Attempt tracking
    attempt_number INTEGER NOT NULL,

    -- HTTP response
    status_code INTEGER NOT NULL DEFAULT 0,
    response_body TEXT,
    response_headers JSONB DEFAULT '{}'::jsonb,

    -- Error tracking
    error TEXT,

    -- Timing metrics
    duration_ms BIGINT DEFAULT 0,

    -- Timestamps
    attempted_at TIMESTAMP WITH TIME ZONE NOT NULL DEFAULT NOW(),

    -- Constraints
    CONSTRAINT {{ident "chk" "attempts_number"}} CHECK (attempt_number > 0),
    CONSTRAINT {{ident "chk" "attempts_status"}} CHECK (status_code >= 0 AND status_code < 600),
    CONSTRAINT {{ident "chk" "attempts_duration"}} CHECK (duration_ms >= 0),

    -- Foreign keys
    CONSTRAINT {{ident "fk" "attempts_delivery"}}
        FOREIGN KEY (delivery_id)
        REFERENCES {{obj "deliveries"}}(id)
        ON DELETE CASCADE
);

-- Indexes for delivery attempts
CREATE INDEX {{ident "idx" "attempts_delivery_id"}} ON {{obj "delivery_attempts"}}(delivery_id);
CREATE INDEX {{ident "idx" "attempts_attempted_at"}} ON {{obj "delivery_attempts"}}(attempted_at DESC);
CREATE INDEX {{ident "idx" "attempts_status_code"}} ON {{obj "delivery_attempts"}}(status_code);
CREATE UNIQUE INDEX {{ident "idx" "attempts_delivery_number"}} ON {{obj "delivery_attempts"}}(delivery_id, attempt_number);

-- Comments
COMMENT ON TABLE {{obj "delivery_attempts"}} IS 'History of all webhook delivery attempts';
COMMENT ON COLUMN {{obj "delivery_attempts"}}.id IS 'Prefixed nanoID (att_*)';
COMMENT ON COLUMN {{obj "delivery_attempts"}}.attempt_number IS '1-based attempt number';
COMMENT ON COLUMN {{obj "delivery_attempts"}}.status_code IS 'HTTP status code (0 if network error)';
COMMENT ON COLUMN {{obj "delivery_attempts"}}.duration_ms IS 'Request duration in milliseconds';

-- =============================================================================
-- IDEMPOTENCY_STORE TABLE
-- =============================================================================
-- Tracks idempotency keys to prevent duplicate deliveries
CREATE TABLE {{obj "idempotency_store"}} (
    -- Composite primary key
    idempotency_key VARCHAR(255) NOT NULL,
    subscription_id VARCHAR(255) NOT NULL,

    -- Expiration
    expires_at TIMESTAMP WITH TIME ZONE NOT NULL,

    -- Timestamps
    created_at TIMESTAMP WITH TIME ZONE NOT NULL DEFAULT NOW(),

    -- Primary key. subscription_id is the idempotency SCOPE: a subscription
    -- id, or "inline:<sha256(tenant, url)>" for inline deliveries — so it has
    -- no foreign key (v0.11.1: the former FK made every keyed inline delivery
    -- fail). Rows expire via expires_at.
    PRIMARY KEY (idempotency_key, subscription_id)
);

-- Indexes for idempotency store
CREATE INDEX {{ident "idx" "idempotency_expires_at"}} ON {{obj "idempotency_store"}}(expires_at);
CREATE INDEX {{ident "idx" "idempotency_subscription_id"}} ON {{obj "idempotency_store"}}(subscription_id);

-- Comments
COMMENT ON TABLE {{obj "idempotency_store"}} IS 'Tracks idempotency keys for exactly-once delivery';
COMMENT ON COLUMN {{obj "idempotency_store"}}.expires_at IS 'Expiration time for automatic cleanup';

-- =============================================================================
-- CIRCUIT_BREAKER_STATE TABLE
-- =============================================================================
-- Stores circuit breaker state per endpoint
CREATE TABLE {{obj "circuit_breaker_state"}} (
    -- Identity (endpoint URL is the key)
    endpoint TEXT PRIMARY KEY,

    -- Circuit state
    state VARCHAR(50) NOT NULL DEFAULT 'closed',

    -- Failure tracking
    failure_count INTEGER NOT NULL DEFAULT 0,
    success_count INTEGER NOT NULL DEFAULT 0,

    -- Timestamps
    last_failure TIMESTAMP WITH TIME ZONE,
    opened_at TIMESTAMP WITH TIME ZONE,
    next_retry_at TIMESTAMP WITH TIME ZONE,
    updated_at TIMESTAMP WITH TIME ZONE NOT NULL DEFAULT NOW(),

    -- Constraints
    CONSTRAINT {{ident "chk" "circuit_state"}} CHECK (state IN ('closed', 'half_open', 'open')),
    CONSTRAINT {{ident "chk" "circuit_failures"}} CHECK (failure_count >= 0),
    CONSTRAINT {{ident "chk" "circuit_successes"}} CHECK (success_count >= 0)
);

-- Indexes for circuit breaker
CREATE INDEX {{ident "idx" "circuit_state"}} ON {{obj "circuit_breaker_state"}}(state);
CREATE INDEX {{ident "idx" "circuit_next_retry"}} ON {{obj "circuit_breaker_state"}}(next_retry_at)
    WHERE state = 'open';

-- Comments
COMMENT ON TABLE {{obj "circuit_breaker_state"}} IS 'Circuit breaker state per webhook endpoint';
COMMENT ON COLUMN {{obj "circuit_breaker_state"}}.state IS 'Current circuit state: closed (normal), half_open (testing), open (failing)';
COMMENT ON COLUMN {{obj "circuit_breaker_state"}}.failure_count IS 'Consecutive failure count';
COMMENT ON COLUMN {{obj "circuit_breaker_state"}}.success_count IS 'Consecutive success count (used in half_open)';

