-- Function to update updated_at timestamp
CREATE OR REPLACE FUNCTION {{obj "update_updated_at"}}()
RETURNS TRIGGER AS $$
BEGIN
    NEW.updated_at = NOW();
    RETURN NEW;
END;
$$ LANGUAGE plpgsql;

-- Trigger for subscriptions.updated_at
CREATE TRIGGER {{ident "trg" "subscriptions_updated_at"}}
    BEFORE UPDATE ON {{obj "subscriptions"}}
    FOR EACH ROW
    EXECUTE FUNCTION {{obj "update_updated_at"}}();

-- Trigger for circuit_breaker_state.updated_at
CREATE TRIGGER {{ident "trg" "circuit_breaker_updated_at"}}
    BEFORE UPDATE ON {{obj "circuit_breaker_state"}}
    FOR EACH ROW
    EXECUTE FUNCTION {{obj "update_updated_at"}}();

-- Function to automatically clean up expired idempotency keys
CREATE OR REPLACE FUNCTION {{obj "cleanup_expired_idempotency"}}()
RETURNS INTEGER AS $$
DECLARE
    deleted_count INTEGER;
BEGIN
    DELETE FROM {{obj "idempotency_store"}}
    WHERE expires_at < NOW();

    GET DIAGNOSTICS deleted_count = ROW_COUNT;
    RETURN deleted_count;
END;
$$ LANGUAGE plpgsql;

-- Comments
COMMENT ON FUNCTION {{obj "update_updated_at"}}() IS 'Automatically updates updated_at timestamp on row modification';
COMMENT ON FUNCTION {{obj "cleanup_expired_idempotency"}}() IS 'Removes expired idempotency keys (call periodically via cron)';

